From 025ad7e7856f6bf7d81d9e3bcb55486416b0e473 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:14:39 +0100
Subject: [PATCH] applets/digital-clock: hide today's events that have already
 ended

The agenda listed every event of the selected day, so today's view kept
showing meetings that were already over. Today's list now leaves out
timed events that have ended, and updates itself when the next one ends.

BUG: 379198
---
 applets/digital-clock/CalendarView.qml | 34 +++++++++++++++++++++++++-
 1 file changed, 33 insertions(+), 1 deletion(-)

diff --git a/applets/digital-clock/CalendarView.qml b/applets/digital-clock/CalendarView.qml
index 48d5dcccb7..429fd72c69 100644
--- a/applets/digital-clock/CalendarView.qml
+++ b/applets/digital-clock/CalendarView.qml
@@ -187,7 +187,39 @@ PlasmaExtras.Representation {
             }

             function updateEventsForCurrentDate() {
-                eventsList.model = monthView.daysModel.eventsForDate(monthView.currentDate);
+                const events = monthView.daysModel.eventsForDate(monthView.currentDate);
+                if (!monthView.isToday(monthView.currentDate)) {
+                    pastEventsTimer.stop();
+                    eventsList.model = events;
+                    return;
+                }
+
+                // Hide today's events that have already ended, and update again when the next one ends
+                const now = new Date();
+                const upcomingEvents = events.filter(event => event.isAllDay || event.endDateTime > now);
+                const nextEnd = Math.min(...upcomingEvents.filter(event => !event.isAllDay).map(event => event.endDateTime - now));
+                if (isFinite(nextEnd)) {
+                    pastEventsTimer.interval = Math.min(nextEnd + 1000, 3600000); // 1hr in ms
+                    pastEventsTimer.restart();
+                } else {
+                    pastEventsTimer.stop();
+                }
+                eventsList.model = upcomingEvents;
+            }
+
+            Timer {
+                id: pastEventsTimer
+                onTriggered: agenda.updateEventsForCurrentDate()
+            }
+
+            Connections {
+                target: root
+
+                function onExpandedChanged() {
+                    if (root.expanded) {
+                        agenda.updateEventsForCurrentDate();
+                    }
+                }
             }

             Connections {
